module.exports = async function (params, ctx, block) {
  const gcmc = ctx.getValue("input_q6zy875zq0eo0k57ya"); // 项目名称
  const jlmc = ctx.getValue("input_kep1zt1ti6dtrf8p6t"); // 监理名称

  if (!gcmc && !jlmc) {
    try {
      // 项目名称
      const resGcmc = await ctx.http.request(
        "POST",
        "/dynamic/function/api/table",
      )({
        tbName: "sys_web_config",
        fields: ["attribute_value"],
        queryMap: { attribute_name: "gcmc" },
      });

      if (resGcmc && resGcmc.length > 0) {
        ctx.setValue("input_q6zy875zq0eo0k57ya", resGcmc[0].attribute_value);
      }

      // 监理名称
      const resJlmc = await ctx.http.request(
        "POST",
        "/dynamic/function/api/table",
      )({
        tbName: "sys_web_config",
        fields: ["attribute_value"],
        queryMap: { attribute_name: "jlmc" },
      });

      if (resJlmc && resJlmc.length > 0) {
        ctx.setValue("input_kep1zt1ti6dtrf8p6t", resJlmc[0].attribute_value);
      }
    } catch (error) {
      console.error("获取配置信息失败:", error);
    }
  }
};

